			"costBasis": "带薪休假权益",
			"compliance": "应核实自由区或行业规则，但阿联酋劳动法基准广泛适用于私营部门员工。",
			"source": "https://u.ae/en/information-and-services/jobs/employment-in-the-private-sector/types-of-leaves-and-entitlements-in-the-private-sector/annual-leave"
