			"basis": "条件性法定福利",
			"employer": "为符合条件的阿联酋国民登记，并缴纳雇主养老金缴费；海湾合作委员会国民可能适用单独规则。",
			"employee": "为受覆盖国民提供养老金、退休、服务终止以及工伤/死亡补偿保障。",
